SINA_SMART["pubhealth1-approaches"] = {"lecture":"pubhealth1-approaches","title":"Public health approaches: prevention and health promotion","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"pubhealth1-approaches:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e0","text":"Prevention: prevent onset, stop progression, reduce consequences (WHO 1984).","topic":"Disease prevention","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e1","text":"Primary: reduce incidence (vaccination, education, smoking cessation); most cost-effective.","topic":"Disease prevention","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e2","text":"Secondary: early detection (screening, TB skin test, contact tracing).","topic":"Disease prevention","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e3","text":"Tertiary: reduce disability and recurrence (rehab, palliation, surveillance).","topic":"Disease prevention","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e4","text":"Screening needs: frequent serious disease, effective treatment, feasible early mass diagnosis.","topic":"Disease prevention","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e5","text":"Health promotion: Ottawa 1986; enabling people to increase control over their health.","topic":"Health promotion (Ottawa, 1986)","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e6","text":"Prerequisites: peace, shelter, education, food, income, ecosystem, resources, justice, equity.","topic":"Health promotion (Ottawa, 1986)","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e7","text":"5 pillars: healthy public policy, supportive environments, community action, personal skills, reorient services.","topic":"Health promotion (Ottawa, 1986)","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"pubhealth1-approaches:e8","text":"Prevention: biomedical, vertical, population as object. Promotion: bio-psycho-social, horizontal, population as subject.","topic":"Prevention vs promotion","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"ua5wjg":"a","1xm862y":"a","ud479w":"a","oatzo1":"a","1jvit0f":"a","1w70mg1":"a","1w5x09n":"a","1rs6owa":"a","5q6ypa":"a","1y70k6s":"a","zh3t6u":"a","12ksg5z":"a","ryyhbg":"a","q4agbo":"a","roaapt":"a","1gyueu":"a","17ua0nl":"a","1v1amng":"a","15rfd4g":"a","1n8u2jn":"a","1ygybwo":"a","m491fi":"x"},"mapCounts":{"verified":0,"auto":21,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"pubhealth1-approaches:s0":{"s":0,"u":["Public health uses several complementary approaches , linked to underlying health models (biomedical, behavioural, socio-environmental): disease prevention , health promotion , primary health care and the One Health approach.","This lecture contrasts the two main ones."],"dp":[{"h":"Why prevention alone is not enough","t":"Prevention programmes tell people what to do about specific risks, which works well for infections with a clear cause. Chronic diseases arise from many interacting determinants (income, education, environment), which directives alone cannot change. Health promotion adds policies, environments and community participation to act on those causes, which is why the lecture calls it the future of public health. Source: the lecture's prevention vs promotion comparison."}]},"pubhealth1-approaches:e0":{"s":1,"u":["Prevention: prevent onset, stop progression, reduce consequences (WHO 1984).","Measures that aim not only to prevent the onset of disease (fighting risk factors) but also to stop its progress and reduce its consequences (WHO glossary, 1984)."],"dp":[]},"pubhealth1-approaches:e1":{"s":1,"u":["Primary: reduce incidence (vaccination, education, smoking cessation); most cost-effective.","Mapped on the natural history of disease: primary prevention reduces incidence (new cases) before exposure: immunisation, health education, smoking cessation; based on relative risk in exposed vs non-exposed people; the most cost-effective ."],"dp":[{"h":"Why primary prevention is the most cost-effective","t":"Every case prevented saves the whole cost of diagnosis, treatment, disability and lost productivity, and a vaccine or a smoking-cessation programme reaches many people for little money. Secondary and tertiary prevention act after disease has started, so they reduce but cannot erase these costs. Source: the lecture's primary prevention slide."}]},"pubhealth1-approaches:e2":{"s":1,"u":["Secondary: early detection (screening, TB skin test, contact tracing).","Secondary prevention : early detection and intervention, ideally before clinical signs: cancer screening, tuberculin skin tests, contact investigations; screening is justified when the disease is frequent enough to cause excess (premature) mortality and cost, an effective treatment exists, and mass early diagnosis is feasible."],"dp":[]},"pubhealth1-approaches:e3":{"s":1,"u":["Tertiary: reduce disability and recurrence (rehab, palliation, surveillance).","Tertiary prevention : reduce the prevalence of chronic disability and recurrence : physiotherapy, rehabilitation, social and professional reintegration, palliative care, surveillance of former cancer patients."],"dp":[]},"pubhealth1-approaches:e4":{"s":1,"u":["Screening needs: frequent serious disease, effective treatment, feasible early mass diagnosis.","Secondary prevention : early detection and intervention, ideally before clinical signs: cancer screening, tuberculin skin tests, contact investigations; screening is justified when the disease is frequent enough to cause excess (premature) mortality and cost, an effective treatment exists, and mass early diagnosis is feasible."],"dp":[]},"pubhealth1-approaches:e5":{"s":2,"u":["Health promotion: Ottawa 1986; enabling people to increase control over their health.","Launched by WHO at the Ottawa conference (1986) : the process of enabling people to increase control over their health and its determinants ."],"dp":[]},"pubhealth1-approaches:e6":{"s":2,"u":["Prerequisites: peace, shelter, education, food, income, ecosystem, resources, justice, equity.","Prerequisites for health : peace, shelter, education, food, income, a stable ecosystem, sustainable resources, social justice and equity."],"dp":[]},"pubhealth1-approaches:e7":{"s":2,"u":["5 pillars: healthy public policy, supportive environments, community action, personal skills, reorient services.","Five action pillars : (1) build healthy public policy (policies shaping living conditions; actors: politicians, influencers/lobbies, the public, the media; tools: advocacy , health impact assessment , intersectoral action , since social inequalities in health arise mainly outside the care system); (2) create supportive environments (physical, psychological, organisational: education, transport, housing, urban planning, workplaces; e.g. health-promoting schools); (3) strengthen community action (mobilisation, participation, empowerment; community = shared belonging; e.g. community dialogue); (4) develop personal skills ( health literacy : finding, understanding and using health information, e.g. linking smoking to cancer); (5) reorient health services (rebalance responsibility between professionals and citizens; 'co-produced' services giving patients a voice, access to records, a say in organisation)."],"dp":[]},"pubhealth1-approaches:e8":{"s":3,"u":["Prevention: biomedical, vertical, population as object. Promotion: bio-psycho-social, horizontal, population as subject.","Health promotion : bio-psycho-social model; horizontal approach through living environments; the population as subject , in collaboration; multifactorial, focused on strengths and advantages; determinants of health .","Disease prevention : biomedical and epidemiological model; vertical approach by programmes; the population as object ; focus on risk factors ; individual responsibility."],"dp":[]}},"meta":{"ua5wjg":{"a":"recall","vg":"pubhealth1-approaches:e1/recall/1"},"1xm862y":{"a":"recall","vg":"pubhealth1-approaches:e1/recall/1"},"ud479w":{"a":"recall","vg":"pubhealth1-approaches:e2/recall/1"},"oatzo1":{"a":"recall","vg":"pubhealth1-approaches:e3/recall/1"},"1jvit0f":{"a":"recall","vg":"pubhealth1-approaches:e1/recall/2"},"1w70mg1":{"a":"recall","vg":"pubhealth1-approaches:e4/recall/1"},"1w5x09n":{"a":"recall","vg":"pubhealth1-approaches:e5/recall/1"},"1rs6owa":{"a":"recall","vg":"pubhealth1-approaches:e5/recall/2"},"5q6ypa":{"a":"recall","vg":"pubhealth1-approaches:e6/recall/1"},"1y70k6s":{"a":"recall","vg":"pubhealth1-approaches:e5/recall/3"},"zh3t6u":{"a":"recall","vg":"pubhealth1-approaches:e7/recall/1"},"12ksg5z":{"a":"recall","vg":"pubhealth1-approaches:e7/recall/2"},"ryyhbg":{"a":"recall","vg":"pubhealth1-approaches:e8/recall/1"},"q4agbo":{"a":"recall","vg":"pubhealth1-approaches:e8/recall/2"},"roaapt":{"a":"application","vg":"pubhealth1-approaches:e3/application/1"},"1gyueu":{"a":"recall","vg":"pubhealth1-approaches:e3/recall/2"},"17ua0nl":{"a":"recall","vg":"pubhealth1-approaches:e6/recall/1"},"1v1amng":{"a":"recall","vg":"pubhealth1-approaches:e7/recall/2"},"15rfd4g":{"a":"recall","vg":"pubhealth1-approaches:e7/recall/3"},"1n8u2jn":{"a":"relationship","vg":"pubhealth1-approaches:e7/relationship/1"},"1ygybwo":{"a":"relationship","vg":"pubhealth1-approaches:e8/relationship/1"}},"explRev":"31841bb6fc87"};
